'use client';

import { BaseCommentsPlugin } from 'platejs/comments';
import { CommentsPlugin } from 'platejs/comments/react';
import { Plate, useCreateEditor, useStaticEditor } from 'platejs/react';

import { BasicBlocksKit } from '@/registry/components/editor/basic-blocks';
import { BaseBasicBlocksKit } from '@/registry/components/editor/basic-blocks-static';
import { commentDecorationAttributes } from '@/registry/components/editor/comment-static';
import { DiscussionKit } from '@/registry/components/editor/discussion';
import { Editor, EditorContainer } from '@/registry/components/editor/editor';
import { EditorStatic } from '@/registry/components/editor/editor-static';
import { LinkKit } from '@/registry/components/editor/link';
import { BaseLinkKit } from '@/registry/components/editor/link-static';
import { SuggestionKit } from '@/registry/components/editor/suggestion';
import {
  commentThreads,
  commentUsers,
  commentValue,
} from '@/registry/examples/values/comment-value';

export default function CommentReviewDemo() {
  const editor = useCreateEditor({
    plugins: [
      ...BasicBlocksKit,
      ...LinkKit,
      ...SuggestionKit,
      ...DiscussionKit,
      CommentsPlugin.configure({
        initialState: {
          currentUserId: 'alice',
          users: commentUsers,
          initialThreads: commentThreads,
        },
      }),
    ],
    initialValue: commentValue.slice(0, 2),
  });
  const staticEditor = useStaticEditor({
    plugins: [
      ...BaseBasicBlocksKit,
      ...BaseLinkKit,
      BaseCommentsPlugin.configure({
        initialState: { initialThreads: commentThreads },
        decorate: { attributes: commentDecorationAttributes },
      }),
    ],
    initialValue: commentValue.slice(0, 2),
  });

  return (
    <div className="flex w-full flex-col gap-6 p-4 sm:p-6">
      <section className="flex flex-col gap-2">
        <h3 className="text-sm font-medium">Read-only document</h3>
        <p className="text-sm text-muted-foreground">
          Open highlights to read and reply. The document itself cannot be
          edited.
        </p>
        <Plate editor={editor} readOnly>
          <EditorContainer className="h-auto rounded-md border" variant="demo">
            <Editor
              aria-label="Read-only comments document"
              className="h-auto px-8 pb-6 sm:px-12"
              readOnly
              variant="demo"
            />
          </EditorContainer>
        </Plate>
      </section>
      <section className="flex flex-col gap-2">
        <h3 className="text-sm font-medium">Static snapshot</h3>
        <p className="text-sm text-muted-foreground">
          The same initial document and ranges, rendered without editing or
          thread controls.
        </p>
        <div className="rounded-md border px-8 py-4">
          <EditorStatic
            aria-label="Static comments document"
            editor={staticEditor}
          />
        </div>
      </section>
    </div>
  );
}

import type { Value } from 'platejs';
import type { CommentThread, CommentUser } from 'platejs/comments';

import { createCommentValue } from '@/registry/components/editor/comment';

export const commentUsers: Record<string, CommentUser> = {
  alice: {
    id: 'alice',
    name: 'Alice',
    avatarUrl: 'https://api.dicebear.com/9.x/glass/svg?seed=alice6',
  },
  bob: {
    id: 'bob',
    name: 'Bob',
    avatarUrl: 'https://api.dicebear.com/9.x/glass/svg?seed=bob4',
  },
  charlie: {
    id: 'charlie',
    name: 'Charlie',
    avatarUrl: 'https://api.dicebear.com/9.x/glass/svg?seed=charlie2',
  },
};

const trailingText =
  ' on many text segments. You can even have overlapping annotations!';

export const commentValue: Value = [
  { type: 'heading', level: 2, children: [{ text: 'Comments' }] },
  {
    type: 'paragraph',
    children: [
      { text: 'Discuss changes using ' },
      { type: 'link', url: '/docs/comment', children: [{ text: 'comments' }] },
      { text: trailingText },
    ],
  },
  {
    type: 'paragraph',
    children: [{ text: 'Select some text and add your own comment as Alice.' }],
  },
];

export const commentThreads: CommentThread[] = [
  {
    id: 'discussion1',
    createdAt: '2026-09-10T10:00:00.000Z',
    resolved: false,
    status: 'published',
    excerpt: 'comments on many text segments',
    userId: 'charlie',
    target: {
      type: 'range',
      range: {
        anchor: { path: [1, 1, 0], offset: 0 },
        focus: { path: [1, 2], offset: trailingText.indexOf('.') },
      },
    },
    messages: [
      {
        id: 'discussion1-comment',
        userId: 'charlie',
        createdAt: '2026-09-10T10:00:00.000Z',
        body: createCommentValue(
          'Comments are a great way to provide feedback and discuss changes.'
        ),
      },
      {
        id: 'discussion1-reply',
        userId: 'bob',
        createdAt: '2026-09-10T10:02:00.000Z',
        body: createCommentValue(
          'Agreed! The link to the docs makes it easy to learn more.'
        ),
      },
    ],
  },
  {
    id: 'discussion2',
    createdAt: '2026-09-10T10:05:00.000Z',
    resolved: false,
    status: 'published',
    excerpt: 'overlapping',
    userId: 'bob',
    target: {
      type: 'range',
      range: {
        anchor: { path: [1, 2], offset: trailingText.indexOf('overlapping') },
        focus: {
          path: [1, 2],
          offset: trailingText.indexOf('overlapping') + 'overlapping'.length,
        },
      },
    },
    messages: [
      {
        id: 'discussion2-comment',
        userId: 'bob',
        createdAt: '2026-09-10T10:05:00.000Z',
        body: createCommentValue(
          'Nice demonstration of overlapping annotations with both comments and suggestions!'
        ),
      },
      {
        id: 'discussion2-reply',
        userId: 'charlie',
        createdAt: '2026-09-10T10:07:00.000Z',
        body: createCommentValue(
          'This helps users understand how powerful the editor can be.'
        ),
      },
    ],
  },
];
